from lib import *
M=mcq;F=tf;S=short;N=num
rows=[('Cube',6,8,12),('Cuboid',6,8,12),('Triangular prism',5,6,9),('Triangular pyramid',4,4,6),('Square pyramid',5,5,8)]
b='<text x="10" y="24" font-weight="bold">Faces, corners and edges of 3D shapes</text><text x="10" y="52">Shape</text><text x="190" y="52">Faces F</text><text x="270" y="52">Corners V</text><text x="360" y="52">Edges E</text><text x="440" y="52">F+V-E</text>'
for i,(n,f,v,e) in enumerate(rows):
    y=80+i*28; b+=f'<text x="10" y="{y}">{n}</text><text x="205" y="{y}">{f}</text><text x="290" y="{y}">{v}</text><text x="375" y="{y}">{e}</text><text x="455" y="{y}" fill="#c0392b" font-weight="bold">{f+v-e}</text>'
b+='<line x1="10" y1="60" x2="500" y2="60" stroke="#333"/>'
svgfile('c4-maths-fve-table.svg',520,230,b)
chapter(4,'maths','shapes-around-us','Shapes Around Us',
 ('Diksha and India Gate','Diksha visited Delhi with her father and saw India Gate, Qutub Minar, Jantar Mantar and Sansad Bhawan. Back home she tried to build a model of India Gate with her wooden blocks. Which shapes would you choose for the pillars, the base and the top?'),
 [('Building models with shapes',['To model a building, pick its parts, such as roof, pillars and base, and choose a solid shape that looks like each part.','Then compare your model with the real building: what is the same and what is different?','Removing one block may change how much the model looks like the building, so every piece matters.','The Qutub Minar is a World Heritage site and the tallest brick building. It has 5 storeys and 379 stairs. Long ago buildings were made with clay bricks, stone blocks or wood, and today we also use concrete and hollow blocks.']),
  ('Nets, prisms and pyramids',['If you open and flatten a box, you get its net. Fold along the dotted lines and you get the box back.','A prism has two matching faces at the ends joined by rectangles, like the triangular prism, square prism and hexagonal prism.','A pyramid has a base and triangular faces that all meet at one point, like the triangular, square and pentagonal pyramids.','So a cube is a square prism, and the difference between a prism and a pyramid is that a pyramid ends in a point.']),
  ('Faces, corners and edges',['A flat part of a solid is a face, a corner is a vertex and the line where two faces meet is an edge.','A cube has 6 faces, 8 corners and 12 edges. A square pyramid has 5 faces, 5 corners and 8 edges.','Add F plus V minus E for each shape. A cube gives 6 plus 8 minus 12, which is 2, and every shape in the table gives 2 as well.','We can sort shapes by the number of flat faces or by straight edges, and shapes with curved faces like a cylinder, cone and sphere go in another group.']),
  ('Looking carefully at a cube',['On a die, the face 1 is opposite 6, 2 is opposite 5 and 3 is opposite 4, so opposite faces add up to 7.','The face numbered 1 shares an edge with four faces, and has no common edge with the opposite face.','Describe a shape by clues: five faces, five corners, eight edges, one square face and four triangles is a square pyramid; one flat and one curved face and one edge is a cone; one curved face with no edge is a sphere.'])],
 [('Find F + V - E for a triangular prism.',[('A triangular prism has 5 faces, 6 corners and 9 edges.','Count each part of the solid.'),('F + V - E = 5 + 6 - 9 = 2.','Add faces and corners, then subtract edges.')]),
  ('Which shape has 5 faces, 5 corners and 8 edges, with one square face?',[('The only solids with five faces are the triangular prism and the square pyramid.','Use the number of faces first.'),('The pyramid has 5 corners and 8 edges, and its square base is one face with 4 triangles.','So it is a square pyramid.')])],
 ('Explain the difference between a prism and a pyramid and count the parts of a cube.',['Prism has two matching ends joined by rectangles','Pyramid has triangles meeting at a point','Cube has 6 faces, 8 corners, 12 edges'],['A cube is not a prism']),
 ['Solid shapes have faces, edges and corners.','A prism has two matching ends; a pyramid has triangles meeting at a point.','For these solids, F + V - E equals 2.'],
 [M('1',1,'How many faces does a cube have?','6',[('4','A cube is not that small'),('8','A cube has 8 corners')],'A cube has 6 square faces, 8 corners and 12 edges.'),
  N('2',1,'How many edges does a square pyramid have?',8,'It has 4 edges on the base and 4 edges going up to the point.',[(5,'5 is the number of faces')]),
  F('3',1,'A cube is also a kind of prism.',True,'A cube is a square prism, because its two opposite ends are squares joined by square faces.'),
  M('4',2,'Which solid has 1 flat face, 1 curved face and 1 edge?','Cone',[('Cylinder','A cylinder has 2 flat faces'),('Sphere','A sphere has no flat face')],'A cone has a flat circular base, a curved face and one edge.'),
  N('5',2,'What is F + V - E for a cuboid?',2,'A cuboid has 6 faces, 8 corners and 12 edges, so 6 + 8 - 12 = 2.',[(14,'You added instead of subtracting edges')]),
  M('6',2,'On a die, which face is opposite the face numbered 2?','5',[('4','4 is opposite 3'),('6','6 is opposite 1')],'Opposite faces of a die add up to 7, so 2 is opposite 5.'),
  S('7',3,'What do we call the flat shape you get by opening up a box?',['net','a net'],'Opening and flattening a box shows its net.'),
  M('8',3,'What is the difference between a prism and a pyramid?','A pyramid has faces that meet at one point',[('A prism has no faces','A prism has flat faces'),('They are the same','Their faces are arranged differently')],'In a pyramid all triangular faces meet at one point; a prism has two matching end faces.')],
 svgs=[('c4-maths-fve-table','Table of faces, corners and edges','Count F, V and E and check F+V-E')])
